cd /var/folders/4_/s6fbcjyn4b13xdxkd3lv0kw00000gn/T/int-I4-claude-none-2-fysekn11/data; cat > /tmp/a.py <<'E'
import csv, statistics as st, datetime as dt, collections as C
P=lambda s:dt.datetime.strptime(s,'%Y-%m-%dT%H:%M:%SZ')
I=list(csv.DictReader(open('incidents.csv')));A={r['incident_id']:r for r in csv.DictReader(open('activity.csv'))}
print(len(I),len(A),len(set(r['incident_id'] for r in I)))
D=[]
for r in I:
    a=A.get(r['incident_id']);r=dict(r);r['o']=P(r['opened_at'])
    if a:
        r['ttc']=(P(a['closed_at'])-r['o']).total_seconds()/3600;r['rm']=float(a['responder_minutes']);r['ho']=int(a['handoffs']);r['re']=int(a['reopened_within_72h'])
    else: r['ttc']=None
    D.append(r)
import pickle;pickle.dump(D,open('/tmp/d.pkl','wb'))
def S(rows,lab):
    c=[r for r in rows if r['ttc'] is not None]
    if not c: print(lab,len(rows),0);return
    q=lambda v,p:sorted(v)[int(p*(len(v)-1))]
    t=[r['ttc'] for r in c]
    print(f"{lab:28} n={len(rows):3} closed={len(c):3} unres={len(rows)-len(c):2} medTTC={st.median(t):6.2f} meanTTC={st.mean(t):6.2f} p90={q(t,.9):6.1f} negTTC={sum(x<0 for x in t)} RMmean={st.mean(r['rm'] for r in c):6.1f} RMmed={st.median(r['rm'] for r in c):6.1f} RMsum={sum(r['rm'] for r in c)/60:7.1f}h ho={st.mean(r['ho'] for r in c):.2f} reo={st.mean(r['re'] for r in c):.3f}")
for k in ['workflow']:
    for v in ['manual','assist']: S([r for r in D if r[k]==v],v)
for k in ['severity','intake_channel','service_group']:
    print(k, {v:dict(C.Counter(r['workflow'] for r in D if r[k]==v)) for v in sorted(set(r[k] for r in D))})
for k in ['severity','intake_channel','service_group']:
    for v in sorted(set(r[k] for r in D)):
        for w in ['manual','assist']: S([r for r in D if r[k]==v and r['workflow']==w],f"{k}={v},{w}")
# check workflow label vs open time
print(C.Counter((r['workflow'],r['o']>=dt.datetime(2026,6,8)) for r in D))
E
python3 -I /tmp/a.py

